//! #417: every transfer the SMF builds or parses, generated codec against the
//! hand-written `nextgcore-ngap` transfer codec it replaced, kept here (as a
//! dev-dependency only) as the ORACLE.
//!
//! Builders: for every input in range the generated bytes are the hand-written
//! bytes -- except the Path Switch Request Acknowledge Transfer with a tunnel,
//! where the hand-written layout was wrong and the difference is pinned
//! exactly. Parsers: on every transfer the hand-written encoder produces, the
//! generated parse reads what the hand-written decoder reads; and the
//! hand-written decoder reads the generated encoder's bytes the same way.

use super::*;
use nextgcore_asn1c::ngap::cause::{Cause, CauseMisc, CauseNas, CauseProtocol, CauseTransport};
use nextgcore_ngap::transfer as hw;
use proptest::prelude::*;

// ---------------------------------------------------------------------------
// The hand-written builders, exactly as smfd drove them before #417.
// ---------------------------------------------------------------------------

fn hw_tunnel((teid, addr): (u32, [u8; 4])) -> hw::UpTransportLayerInformation {
    hw::UpTransportLayerInformation::GtpTunnel(hw::GtpTunnel {
        transport_layer_address: hw::TransportLayerAddress::from_ipv4(addr),
        gtp_teid: teid.to_be_bytes(),
    })
}

fn hw_setup_request(r: &SetupRequest) -> nextgcore_ngap::NgapResult<Vec<u8>> {
    hw::PduSessionResourceSetupRequestTransfer {
        pdu_session_aggregate_maximum_bit_rate: r
            .ambr
            .map(|(dl, ul)| hw::PduSessionAggregateMaximumBitRate { dl, ul }),
        ul_ngu_up_tnl_information: hw_tunnel(r.ul_tunnel),
        data_forwarding_not_possible: r.data_forwarding_not_possible,
        direct_forwarding_path_availability: r.direct_forwarding_path_availability,
        pdu_session_type: hw::PduSessionType::Ipv4,
        security_indication: None,
        network_instance: None,
        qos_flow_setup_request_list: r
            .flows
            .iter()
            .map(|f| hw::QosFlowSetupRequestItem {
                qos_flow_identifier: f.qfi,
                qos_flow_level_qos_parameters: hw::QosFlowLevelQosParameters {
                    qos_characteristics: hw::QosCharacteristics::NonDynamic5qi(
                        hw::NonDynamic5qiDescriptor::new(f.five_qi),
                    ),
                    allocation_and_retention_priority: hw::AllocationAndRetentionPriority {
                        priority_level_arp: f.arp.priority_level,
                        pre_emption_capability: if f.arp.may_trigger_pre_emption {
                            hw::PreEmptionCapability::MayTriggerPreEmption
                        } else {
                            hw::PreEmptionCapability::ShallNotTriggerPreEmption
                        },
                        pre_emption_vulnerability: if f.arp.pre_emptable {
                            hw::PreEmptionVulnerability::PreEmptable
                        } else {
                            hw::PreEmptionVulnerability::NotPreEmptable
                        },
                    },
                    gbr_qos_information: f.gbr.map(|g| hw::GbrQosInformation {
                        maximum_flow_bit_rate_dl: g.mfbr_dl,
                        maximum_flow_bit_rate_ul: g.mfbr_ul,
                        guaranteed_flow_bit_rate_dl: g.gfbr_dl,
                        guaranteed_flow_bit_rate_ul: g.gfbr_ul,
                        notification_control: false,
                        maximum_packet_loss_rate_dl: None,
                        maximum_packet_loss_rate_ul: None,
                    }),
                    reflective_qos_attribute: false,
                    additional_qos_flow_information: false,
                },
                e_rab_id: f.e_rab_id,
            })
            .collect(),
    }
    .encode()
}

fn hw_modify_request(ambr: Option<(u64, u64)>, qfis: &[u8]) -> nextgcore_ngap::NgapResult<Vec<u8>> {
    hw::PduSessionResourceModifyRequestTransfer {
        pdu_session_aggregate_maximum_bit_rate: ambr
            .map(|(dl, ul)| hw::PduSessionAggregateMaximumBitRate { dl, ul }),
        qos_flow_add_or_modify_request_list: qfis
            .iter()
            .map(|&q| hw::QosFlowAddOrModifyRequestItem {
                qos_flow_identifier: q,
                qos_flow_level_qos_parameters: None,
                e_rab_id: None,
            })
            .collect(),
        ..Default::default()
    }
    .encode()
}

fn hw_cause(cause: SmfCause) -> Cause {
    match cause {
        SmfCause::NasNormalRelease => Cause::Nas(CauseNas::NormalRelease),
        SmfCause::TransportResourceUnavailable => {
            Cause::Transport(CauseTransport::TransportResourceUnavailable)
        }
        SmfCause::TransportUnspecified => Cause::Transport(CauseTransport::Unspecified),
        SmfCause::ProtocolFalselyConstructedMessage => {
            Cause::Protocol(CauseProtocol::AbstractSyntaxErrorFalselyConstructedMessage)
        }
        SmfCause::MiscUnspecified => Cause::Misc(CauseMisc::Unspecified),
    }
}

const ALL_CAUSES: [SmfCause; 5] = [
    SmfCause::NasNormalRelease,
    SmfCause::TransportResourceUnavailable,
    SmfCause::TransportUnspecified,
    SmfCause::ProtocolFalselyConstructedMessage,
    SmfCause::MiscUnspecified,
];

/// What the SMF read off a hand-written decoded tunnel and flow list.
fn hw_endpoint(t: &hw::UpTransportLayerInformation, qfis: Vec<u8>) -> DlEndpoint {
    let hw::UpTransportLayerInformation::GtpTunnel(t) = t;
    DlEndpoint {
        teid: u32::from_be_bytes(t.gtp_teid),
        address: t.transport_layer_address.octets.clone(),
        bit_len: t.transport_layer_address.bit_len,
        qfis,
    }
}

fn hw_per_tnl(tunnel: (u32, [u8; 4]), qfis: &[u8]) -> hw::QosFlowPerTnlInformation {
    hw::QosFlowPerTnlInformation {
        up_transport_layer_information: hw_tunnel(tunnel),
        associated_qos_flow_list: qfis
            .iter()
            .map(|&q| hw::AssociatedQosFlowItem {
                qos_flow_identifier: q,
                qos_flow_mapping_indication: None,
            })
            .collect(),
    }
}

// ---------------------------------------------------------------------------
// Strategies, all within the ranges the schema and the SMF allow.
// ---------------------------------------------------------------------------

fn tunnel() -> impl Strategy<Value = (u32, [u8; 4])> {
    (any::<u32>(), any::<[u8; 4]>())
}

/// BitRate ::= INTEGER (0..4000000000000, ...)
fn bit_rate() -> impl Strategy<Value = u64> {
    prop_oneof![
        Just(0u64),
        0u64..=4_000_000_000_000,
        Just(4_000_000_000_000)
    ]
}

fn flow() -> impl Strategy<Value = QosFlowSetup> {
    (
        0u8..=MAX_QFI,
        0u16..=255,
        (1u8..=15, any::<bool>(), any::<bool>()),
        proptest::option::of((bit_rate(), bit_rate(), bit_rate(), bit_rate())),
        proptest::option::of(0u8..=15),
    )
        .prop_map(
            |(qfi, five_qi, (priority_level, cap, vuln), gbr, e_rab_id)| QosFlowSetup {
                qfi,
                five_qi,
                arp: Arp {
                    priority_level,
                    may_trigger_pre_emption: cap,
                    pre_emptable: vuln,
                },
                gbr: gbr.map(|(mfbr_dl, mfbr_ul, gfbr_dl, gfbr_ul)| Gbr {
                    mfbr_dl,
                    mfbr_ul,
                    gfbr_dl,
                    gfbr_ul,
                }),
                e_rab_id,
            },
        )
}

fn setup_request() -> impl Strategy<Value = SetupRequest> {
    (
        proptest::option::of((bit_rate(), bit_rate())),
        tunnel(),
        any::<bool>(),
        any::<bool>(),
        proptest::collection::vec(flow(), 1..=4),
    )
        .prop_map(|(ambr, ul_tunnel, dfnp, dfpa, flows)| SetupRequest {
            ambr,
            ul_tunnel,
            data_forwarding_not_possible: dfnp,
            direct_forwarding_path_availability: dfpa,
            flows,
        })
}

fn qfis(range: std::ops::RangeInclusive<usize>) -> impl Strategy<Value = Vec<u8>> {
    proptest::collection::vec(0u8..=MAX_QFI, range)
}

proptest! {
    #![proptest_config(ProptestConfig::with_cases(256))]

    #[test]
    fn setup_request_transfer_is_the_hand_written_bytes(r in setup_request()) {
        prop_assert_eq!(setup_request_transfer(&r).unwrap(), hw_setup_request(&r).unwrap());
    }

    #[test]
    fn modify_request_transfer_is_the_hand_written_bytes(
        ambr in proptest::option::of((bit_rate(), bit_rate())),
        q in qfis(0..=4),
    ) {
        prop_assert_eq!(modify_request_transfer(ambr, &q).unwrap(), hw_modify_request(ambr, &q).unwrap());
    }

    #[test]
    fn modify_confirm_transfer_is_the_hand_written_bytes(q in qfis(1..=64), ul in tunnel()) {
        let old = hw::PduSessionResourceModifyConfirmTransfer {
            qos_flow_modify_confirm_list: q.clone(),
            ul_ngu_up_tnl_information: hw_tunnel(ul),
            qos_flow_failed_to_modify_list: Vec::new(),
        }
        .encode()
        .unwrap();
        prop_assert_eq!(modify_confirm_transfer(&q, ul).unwrap(), old);
    }

    #[test]
    fn setup_response_transfer_parses_as_the_hand_written_decoder_reads_it(
        dl in tunnel(),
        q in qfis(1..=4),
        additional in proptest::collection::vec((tunnel(), qfis(1..=2)), 0..=3),
    ) {
        let bytes = hw::PduSessionResourceSetupResponseTransfer {
            dl_qos_flow_per_tnl_information: hw_per_tnl(dl, &q),
            additional_dl_qos_flow_per_tnl_information: additional
                .iter()
                .map(|(t, q)| hw_per_tnl(*t, q))
                .collect(),
            security_result: None,
            qos_flow_failed_to_setup_list: Vec::new(),
        }
        .encode()
        .unwrap();
        let old = hw::PduSessionResourceSetupResponseTransfer::decode(&bytes).unwrap();
        let old = hw_endpoint(
            &old.dl_qos_flow_per_tnl_information.up_transport_layer_information,
            old.dl_qos_flow_per_tnl_information
                .associated_qos_flow_list
                .iter()
                .map(|f| f.qos_flow_identifier)
                .collect(),
        );
        prop_assert_eq!(parse_setup_response_transfer(&bytes).unwrap(), old);
    }

    #[test]
    fn modify_indication_transfer_parses_as_the_hand_written_decoder_reads_it(
        dl in tunnel(),
        q in qfis(1..=4),
        additional in proptest::collection::vec((tunnel(), qfis(1..=2)), 0..=3),
    ) {
        let bytes = hw::PduSessionResourceModifyIndicationTransfer {
            dl_qos_flow_per_tnl_information: hw_per_tnl(dl, &q),
            additional_dl_qos_flow_per_tnl_information: additional
                .iter()
                .map(|(t, q)| hw_per_tnl(*t, q))
                .collect(),
        }
        .encode()
        .unwrap();
        let old = hw::PduSessionResourceModifyIndicationTransfer::decode(&bytes).unwrap();
        let expected = ModifyIndication {
            dl: hw_endpoint(
                &old.dl_qos_flow_per_tnl_information.up_transport_layer_information,
                old.dl_qos_flow_per_tnl_information
                    .associated_qos_flow_list
                    .iter()
                    .map(|f| f.qos_flow_identifier)
                    .collect(),
            ),
            additional_dl_tunnels: old.additional_dl_qos_flow_per_tnl_information.len(),
        };
        prop_assert_eq!(parse_modify_indication_transfer(&bytes).unwrap(), expected);
    }

    #[test]
    fn handover_request_acknowledge_transfer_parses_as_the_hand_written_decoder_reads_it(
        dl in tunnel(),
        forwarding in proptest::option::of(tunnel()),
        flows in proptest::collection::vec((0u8..=MAX_QFI, any::<bool>()), 1..=4),
    ) {
        let bytes = hw::HandoverRequestAcknowledgeTransfer {
            dl_ngu_up_tnl_information: hw_tunnel(dl),
            dl_forwarding_up_tnl_information: forwarding.map(hw_tunnel),
            security_result: None,
            qos_flow_setup_response_list: flows
                .iter()
                .map(|&(q, accepted)| hw::QosFlowItemWithDataForwarding {
                    qos_flow_identifier: q,
                    data_forwarding_accepted: accepted,
                })
                .collect(),
            qos_flow_failed_to_setup_list: Vec::new(),
            data_forwarding_response_drb_list: Vec::new(),
        }
        .encode()
        .unwrap();
        let old = hw::HandoverRequestAcknowledgeTransfer::decode(&bytes).unwrap();
        let old = hw_endpoint(
            &old.dl_ngu_up_tnl_information,
            old.qos_flow_setup_response_list
                .iter()
                .map(|f| f.qos_flow_identifier)
                .collect(),
        );
        prop_assert_eq!(parse_handover_request_acknowledge_transfer(&bytes).unwrap(), old);
    }

    /// The hand-written codec has no PathSwitchRequestTransfer encoder (the SMF
    /// never sends one), so the bytes come from the generated encoder and both
    /// decoders must read them alike.
    #[test]
    fn path_switch_request_transfer_parses_as_the_hand_written_decoder_reads_it(
        dl in tunnel(),
        q in qfis(1..=64),
    ) {
        let bytes = generated_path_switch_request(dl, &q, false);
        let old = hw::PathSwitchRequestTransfer::decode(&bytes).unwrap();
        let old = hw_endpoint(&old.dl_ngu_up_tnl_information, old.qos_flow_accepted_list);
        prop_assert_eq!(parse_path_switch_request_transfer(&bytes).unwrap(), old);
    }

    /// The hand-written decoder reads what the SMF now builds as it read what it
    /// used to build, for every transfer it has a decoder for.
    #[test]
    fn the_hand_written_decoders_read_the_generated_bytes(
        r in setup_request(),
        ambr in proptest::option::of((bit_rate(), bit_rate())),
        q in qfis(1..=4),
        ul in tunnel(),
    ) {
        let setup = hw::PduSessionResourceSetupRequestTransfer::decode(
            &setup_request_transfer(&r).unwrap(),
        )
        .unwrap();
        prop_assert_eq!(setup.encode().unwrap(), hw_setup_request(&r).unwrap());

        let modify = hw::PduSessionResourceModifyRequestTransfer::decode(
            &modify_request_transfer(ambr, &q).unwrap(),
        )
        .unwrap();
        prop_assert_eq!(modify.encode().unwrap(), hw_modify_request(ambr, &q).unwrap());

        let confirm = hw::PduSessionResourceModifyConfirmTransfer::decode(
            &modify_confirm_transfer(&q, ul).unwrap(),
        )
        .unwrap();
        prop_assert_eq!(confirm.qos_flow_modify_confirm_list, q);
        prop_assert_eq!(confirm.ul_ngu_up_tnl_information, hw_tunnel(ul));
    }
}

/// A generated-codec PathSwitchRequestTransfer, optionally carrying User Plane
/// Security Information.
fn generated_path_switch_request(dl: (u32, [u8; 4]), qfis: &[u8], security: bool) -> Vec<u8> {
    encode(
        "test",
        &g::PathSwitchRequestTransfer {
            dl_ngu_up_tnl_information: gtp_tunnel(dl),
            dl_ngu_tnl_information_reused: None,
            user_plane_security_information: security.then_some(g::UserPlaneSecurityInformation {
                security_result: g::SecurityResult {
                    integrity_protection_result: g::IntegrityProtectionResult(
                        g::IntegrityProtectionResult::PERFORMED,
                    ),
                    confidentiality_protection_result: g::ConfidentialityProtectionResult(
                        g::ConfidentialityProtectionResult::PERFORMED,
                    ),
                    ie_extensions: None,
                },
                security_indication: g::SecurityIndication {
                    integrity_protection_indication: g::IntegrityProtectionIndication(
                        g::IntegrityProtectionIndication::REQUIRED,
                    ),
                    confidentiality_protection_indication: g::ConfidentialityProtectionIndication(
                        g::ConfidentialityProtectionIndication::REQUIRED,
                    ),
                    maximum_integrity_protected_data_rate_ul: None,
                    ie_extensions: None,
                },
                ie_extensions: None,
            }),
            qos_flow_accepted_list: g::QosFlowAcceptedList(
                qfis.iter()
                    .map(|&q| g::QosFlowAcceptedItem {
                        qos_flow_identifier: g::QosFlowIdentifier(q),
                        ie_extensions: None,
                    })
                    .collect(),
            ),
            ie_extensions: None,
        },
    )
    .unwrap()
}

#[test]
fn cause_transfers_are_the_hand_written_bytes() {
    for cause in ALL_CAUSES {
        assert_eq!(
            modify_indication_unsuccessful_transfer(cause).unwrap(),
            hw::PduSessionResourceModifyIndicationUnsuccessfulTransfer {
                cause: hw_cause(cause)
            }
            .encode()
            .unwrap(),
            "{cause:?}"
        );
    }
    assert_eq!(
        release_command_transfer().unwrap(),
        hw::PduSessionResourceReleaseCommandTransfer {
            cause: hw_cause(SmfCause::NasNormalRelease)
        }
        .encode()
        .unwrap()
    );
}

/// The no-change form is one octet in both layouts: all presence bits zero.
#[test]
fn an_empty_path_switch_acknowledge_is_the_hand_written_bytes() {
    let new = path_switch_request_acknowledge_transfer(None).unwrap();
    assert_eq!(new, vec![0x00]);
    assert_eq!(
        new,
        hw::PathSwitchRequestAcknowledgeTransfer::default()
            .encode()
            .unwrap()
    );
}

/// TS 38.413 §9.3.4.9 / the Rel-17 ASN.1:
///
/// ```text
/// PathSwitchRequestAcknowledgeTransfer ::= SEQUENCE {
///     uL-NGU-UP-TNLInformation  UPTransportLayerInformation  OPTIONAL,
///     securityIndication        SecurityIndication           OPTIONAL,
///     iE-Extensions  ProtocolExtensionContainer { {...} }    OPTIONAL,
///     ...
/// }
/// ```
///
/// Three presence bits after the extension bit. The hand-written encoder wrote
/// five -- two for `newSecurityResult` and `qosFlowToReleaseList`, which this
/// SEQUENCE does not have.
///
/// Both vectors are derived by hand (X.691 ALIGNED), for UL tunnel
/// 10.45.0.1 / TEID 0x00010001:
///
/// ```text
/// generated:    0 1 0 0          ext, uL-NGU-UP-TNLInformation, securityIndication, iE-Ext
///               0                UPTransportLayerInformation CHOICE index 0 (gTPTunnel)
///               0 0              GTPTunnel ext, iE-Extensions
///               0                TransportLayerAddress SIZE ext
///               0001 1111        length 32 - 1, 8-bit field (range 160)
///               0a 2d 00 01      the address, octet-aligned (bit 16 already is)
///               00 01 00 01      GTP-TEID, SIZE(4) fixed
///            =  40 1f 0a 2d 00 01 00 01 00 01
///
/// hand-written: 0 1 0 0 0 0      two spurious presence bits
///               0 0 0 0 0001 1111 + 6 padding bits, then the same 8 octets
///            =  40 07 c0 0a 2d 00 01 00 01 00 01
/// ```
///
/// A conformant decoder reads the hand-written bytes as an 8-bit address
/// (length field 0x07) of 0xc0 and TEID 0x0a2d0001.
#[test]
fn path_switch_acknowledge_follows_the_schema_not_the_hand_written_layout() {
    let ul = (0x0001_0001, [10, 45, 0, 1]);
    let new = path_switch_request_acknowledge_transfer(Some(ul)).unwrap();
    let old = hw::PathSwitchRequestAcknowledgeTransfer {
        ul_ngu_up_tnl_information: Some(hw_tunnel(ul)),
        ..Default::default()
    }
    .encode()
    .unwrap();
    assert_eq!(
        new,
        [0x40, 0x1f, 0x0a, 0x2d, 0x00, 0x01, 0x00, 0x01, 0x00, 0x01]
    );
    assert_eq!(
        old,
        [0x40, 0x07, 0xc0, 0x0a, 0x2d, 0x00, 0x01, 0x00, 0x01, 0x00, 0x01]
    );

    // The generated decoder -- what a conformant gNB runs -- reads the tunnel
    // from the new bytes, and a different one from the old.
    let read = |bytes: &[u8]| {
        nextgcore_ngap_gen::decode_contained::<g::PathSwitchRequestAcknowledgeTransfer>(bytes)
            .unwrap()
            .ul_ngu_up_tnl_information
            .map(|t| endpoint("test", t, Vec::new()).unwrap())
    };
    assert_eq!(
        read(&new),
        Some(DlEndpoint {
            teid: 0x0001_0001,
            address: vec![10, 45, 0, 1],
            bit_len: 32,
            qfis: Vec::new(),
        })
    );
    assert_eq!(
        read(&old),
        Some(DlEndpoint {
            teid: 0x0a2d_0001,
            address: vec![0xc0],
            bit_len: 8,
            qfis: Vec::new(),
        })
    );
}

/// The hand-written decoder refused a PathSwitchRequestTransfer carrying User
/// Plane Security Information (it could not skip it); the generated parse reads
/// past it to the same endpoint.
#[test]
fn a_path_switch_request_with_user_plane_security_information_is_now_read() {
    let dl = (0x0abc_def0, [192, 0, 2, 7]);
    let bytes = generated_path_switch_request(dl, &[1, 5], true);
    assert!(hw::PathSwitchRequestTransfer::decode(&bytes).is_err());
    assert_eq!(
        parse_path_switch_request_transfer(&bytes).unwrap(),
        DlEndpoint {
            teid: 0x0abc_def0,
            address: vec![192, 0, 2, 7],
            bit_len: 32,
            qfis: vec![1, 5],
        }
    );
}

/// What the hand-written encoder refused, the generated builders refuse too.
#[test]
fn out_of_range_values_are_refused_as_before() {
    let base = SetupRequest {
        ambr: None,
        ul_tunnel: (1, [10, 0, 0, 1]),
        data_forwarding_not_possible: false,
        direct_forwarding_path_availability: false,
        flows: vec![QosFlowSetup {
            qfi: 1,
            five_qi: 9,
            arp: Arp {
                priority_level: 8,
                may_trigger_pre_emption: false,
                pre_emptable: false,
            },
            gbr: None,
            e_rab_id: None,
        }],
    };
    let with = |f: &dyn Fn(&mut QosFlowSetup)| {
        let mut r = base.clone();
        f(&mut r.flows[0]);
        r
    };
    for (name, r) in [
        ("QFI 64", with(&|f| f.qfi = 64)),
        ("ARP 0", with(&|f| f.arp.priority_level = 0)),
        ("ARP 16", with(&|f| f.arp.priority_level = 16)),
        (
            "no flows",
            SetupRequest {
                flows: Vec::new(),
                ..base.clone()
            },
        ),
    ] {
        assert!(
            hw_setup_request(&r).is_err(),
            "{name}: the oracle refused it"
        );
        assert!(setup_request_transfer(&r).is_err(), "{name}");
    }
    assert!(setup_request_transfer(&with(&|f| f.five_qi = 256)).is_err());
    assert!(modify_request_transfer(None, &[64]).is_err());
    assert!(hw_modify_request(None, &[64]).is_err());
    assert!(modify_confirm_transfer(&[], (1, [10, 0, 0, 1])).is_err());
    assert!(modify_confirm_transfer(&[64], (1, [10, 0, 0, 1])).is_err());
}

/// A Setup Response Transfer whose iE-Extensions carry one entry with an id the
/// schema does not define (9), at each criticality. The hand-written decoder
/// refused it at `reject` and skipped it otherwise; so does the generated parse.
#[test]
fn an_unknown_extension_is_skipped_unless_its_criticality_is_reject() {
    let dl = (0x0000_0007, [10, 45, 0, 3]);
    let transfer = |extensions| g::PDUSessionResourceSetupResponseTransfer {
        dl_qos_flow_per_tnl_information: g::QosFlowPerTNLInformation {
            up_transport_layer_information: gtp_tunnel(dl),
            associated_qos_flow_list: g::AssociatedQosFlowList(vec![g::AssociatedQosFlowItem {
                qos_flow_identifier: g::QosFlowIdentifier(9),
                qos_flow_mapping_indication: None,
                ie_extensions: None,
            }]),
            ie_extensions: None,
        },
        additional_dl_qos_flow_per_tnl_information: None,
        security_result: None,
        qos_flow_failed_to_setup_list: None,
        ie_extensions: extensions,
    };
    // A one-entry container of a KNOWN extension (MBS Support Indicator, id 309),
    // which the codec puts octet-aligned at the very end of the transfer.
    let container = g::PDUSessionResourceSetupResponseTransferIE_Extensions(vec![
        g::PDUSessionResourceSetupResponseTransferIE_Extensions_Entry {
            id: g::ProtocolExtensionID(309),
            criticality: g::Criticality(g::Criticality::IGNORE),
            extension_value:
                g::PDUSessionResourceSetupResponseTransferIE_Extensions_EntryExtensionValue::Id_MBS_SupportIndicator(
                    g::MBS_SupportIndicator(g::MBS_SupportIndicator::TRUE),
                ),
        },
    ]);
    let container_bytes = nextgcore_ngap_gen::encode_contained(&container).unwrap();
    assert_eq!(
        &container_bytes[..4],
        &[0x00, 0x00, 0x01, 0x35],
        "count - 1, id 309"
    );
    let known = encode("test", &transfer(Some(container))).unwrap();
    let at = known.len() - container_bytes.len();
    assert_eq!(&known[at..], &container_bytes[..]);

    let expected = DlEndpoint {
        teid: 7,
        address: vec![10, 45, 0, 3],
        bit_len: 32,
        qfis: vec![9],
    };
    assert_eq!(parse_setup_response_transfer(&known).unwrap(), expected);
    for (criticality, accepted) in [
        (g::Criticality::REJECT, false),
        (g::Criticality::IGNORE, true),
        (g::Criticality::NOTIFY, true),
    ] {
        let mut bytes = known.clone();
        bytes[at + 2..at + 4].copy_from_slice(&9u16.to_be_bytes());
        bytes[at + 4] = criticality << 6;
        assert_eq!(
            parse_setup_response_transfer(&bytes).ok(),
            accepted.then(|| expected.clone()),
            "criticality {criticality}"
        );
        assert_eq!(
            hw::PduSessionResourceSetupResponseTransfer::decode(&bytes).is_ok(),
            accepted,
            "the oracle, criticality {criticality}"
        );
    }
}
